    env["HOME"] = home
    env["TERM"] = "dumb"
    env["LC_ALL"] = "C"
    env["HISTFILE"] = "/dev/null"

    pid, fd = pty.fork()
    if pid == 0:
        # Child: exec bash.
        os.chdir(home)
        os.environ.clear()
        os.environ.update(env)
        os.execvpe(
            "/bin/bash",
            ["bash", "--noprofile", "--rcfile", rcfile, "-i"],
            env,
        )

    chunks = []
    closed = False
    try:
